def alternatives() -> dict[str, list[str]]:
    result = {}
    for line in RAW_ALTERNATIVES.strip().splitlines():
        family, *values = line.split('|')
        assert len(values) == 4
        result[family] = values
    assert len(result) == 50
    return result


def parse_profiles() -> list[dict]:
    profiles = []
    for raw in RAW_PROFILES.strip().splitlines():
        cols = raw.split("|")
        assert len(cols) == 16, (cols[0], len(cols))
        family, scenario, title, scope, *rest = cols
        profiles.append(dict(family_id=family, scenario=scenario, title=title, scope=scope,
                             facts=rest[:6], queries=rest[6:]))
    assert len(profiles) == 50
    by_id = {p['family_id']: p for p in profiles}
    # Pre-score audit corrections: keep both cross-section labels sufficient,
    # and state action preconditions instead of implying them from a topic.
    by_id['sso_clock']['facts'][5] = by_id['sso_clock']['facts'][5].replace(
        '三个时间值', '终端时间、受管时间源时间和断言生效时间')
    by_id['mysql_replica']['facts'][5] = by_id['mysql_replica']['facts'][5].replace(
        '两类位点', '接收位点和应用位点')
    by_id['dns_negative']['queries'][5] = '确认权威查询成功且负缓存未过期时先如何恢复，恢复后仍返回旧结果应向哪组提交什么？'
    by_id['ad_lock']['queries'][5] = '确认用户近期改过密码且旧密码重试来自本人手机后先怎么恢复，处理后仍锁定时应向哪组交什么？'
    by_id['k8s_dns']['queries'][5] = '确认DNS阻断仅来自命名空间出口规则后先怎么恢复，仍超时要交给谁和哪些材料？'
    return profiles


def provenance(method: str, **extra) -> dict:
    return {
        "source": "fictional_company_internal_runbook",
        "generation_method": method,
        "authorship": "LLM-authored synthetic policies; no external source attribution",
        "vendor_normative": False,
        **extra,
    }


def paragraph(scope: str, fact: str, index: int) -> str:
    text = f"适用范围：{scope}。{fact}{SECTION_NOTES[index]}"
    # Keep each H2 paragraph reasonably close to a realistic evidence passage,
    # without splitting the complete fact or repeating it in a document title.
    if len(text) > 225:
        text = f"适用范围：{scope}。{fact}{SECTION_NOTES[index].split('。')[0]}。"
    assert 100 <= len(text) <= 225, (len(text), scope)
    return text


def body_for(title: str, scope: str, facts: list[str]) -> str:
    return "# " + title + "\n\n" + "\n\n".join(
        f"## {name}\n\n{paragraph(scope, fact, i)}"
        for i, (name, fact) in enumerate(zip(SECTION_NAMES, facts, strict=True))
    )


def target_document(profile: dict, split: str) -> dict:
    return {
        "id": "target-" + profile["family_id"],
        "title": profile["title"],
        "body": body_for(profile["title"], profile["scope"], profile["facts"]),
        "scenario": profile["scenario"], "status": "active", "valid_to": "2099-12-31",
        "kind": "target", "family_id": profile["family_id"], "split": split,
        "applicability": profile["scope"],
        "provenance": provenance("llm_composed_family_facts_and_questions"),
    }


def questions_for(profile: dict, split: str) -> list[dict]:
    questions = []
    doc_id = "target-" + profile["family_id"]
    for i, question in enumerate(profile["queries"]):
        gold_indices = [i] if i < 5 else [2, 5]
        gold = [{"document_id": doc_id, "section": SECTION_NAMES[j], "section_index": j + 1,
                 "evidence": profile["facts"][j]} for j in gold_indices]
        questions.append({
            "question_id": f"{profile['family_id']}-q{i + 1}",
            "family_id": profile["family_id"], "split": split,
            "query": f"在{profile['scope']}中，{question}",
            "question_type": QUESTION_TYPES[i],
            "conditions": {"scope": profile["scope"], "required_status": "active", "as_of": "2026-11-02"},
            "gold": gold,
            "answer": " ".join(profile["facts"][j] for j in gold_indices),
            "provenance": provenance("llm_composed_fact_supported_question",
                                     evidence_source=doc_id, evidence_only=True),
        })
    return questions


# Twelve deliberately incompatible operating contexts. Every distractor changes
# the environment from the target's production scope and also changes one of
# ownership, version, failure cause, action, safety policy, or acceptance target.
# These are hard lexical/topic negatives, not verified real incident negatives.
VARIANTS = [
    ("灾备演练网", "兼容版", "凭据轮换未同步", "轮换记录缺少最后一次部署确认", "重新部署演练专用凭据", "演练账号认证成功且不影响生产账号", "credential_epoch"),
    ("隔离验收网", "候选版", "访问策略被主动收紧", "审批表已经撤回该测试对象权限", "保持拒绝状态并回退验收用例", "拒绝审计完整且无越权连接", "authorization_policy"),
    ("供应商联调网", "联调版", "外部代理改写了请求目标", "联调代理请求目标与登记端点不同", "修正联调代理目标映射", "联调目标与登记一致且脱敏追踪可对齐", "routing_destination"),
    ("开发沙箱网", "实验版", "本地模拟时钟偏差", "模拟器时间不属于公司受管时间源", "重置沙箱模拟时钟并重放测试请求", "模拟时间回到用例时间窗且不触及宿主时钟", "clock_source"),
    ("培训实训网", "教学版", "预置示例配置损坏", "培训初始化文件的校验和不一致", "从课程只读镜像恢复示例配置", "样例校验通过且学员数据未被覆盖", "configuration_integrity"),
    ("性能压测网", "压测版", "并发超过预留容量", "压测阶梯上升时资源指标同步饱和", "降低发压并发并恢复到容量预约范围", "资源回落且压测请求符合预约上限", "capacity_limit"),
    ("迁移验证网", "迁移版", "新旧端点登记混用", "任务仍引用迁移前的退役端点", "切换到迁移清单中批准的新端点", "验证流量只到新端点且旧端点无请求", "endpoint_lifecycle"),
    ("离线应急网", "应急版", "依赖离线介质未挂载", "依赖清单要求介质且当前挂载列表缺项", "核验应急介质签名后以只读方式挂载", "依赖可读且应急介质保持只读", "dependency_availability"),
    ("旧系统退役网", "退役版", "服务已按退役计划关闭", "退役审批已生效且端点不再提供服务", "保留关闭状态并撤销调用方旧登记", "旧调用停止且退役审计完整", "service_lifecycle"),
    ("双活切换演习网", "演习版", "演习流量标签丢失", "请求追踪中缺少演习租户标签", "恢复演习标签注入并重新建立测试会话", "演习请求归属正确且生产租户无新增流量", "tenant_attribution"),
    ("内部安全验证网", "加固版", "安全测试故意注入拒绝", "故障注入记录覆盖当前测试时间窗", "结束已审批的故障注入并撤销临时规则", "注入规则撤销且原有安全基线仍生效", "fault_injection"),
    ("边缘试点网", "试点版", "试点节点配置尚未分发", "配置发布记录中该节点仍处于等待批次", "等待试点发布窗口再同步批准配置", "节点配置版本与试点批次一致且变更可回退", "deployment_batch"),
]


def distractor_document(profile: dict, split: str, variant_index: int) -> dict:
    environment, version, cause, diagnostic, action, verify, conflict = VARIANTS[variant_index]
    # Keep actual product terminology but replace ALL target network/domain
    # applicability; never reuse the exact production scope as a positive fact.
    product_parts = profile["scope"].split("、")
    product_parts[0] = re.sub(r"\d+(?:\.\d+)*", "", product_parts[0]).strip() + version
    product_parts[-1] = environment
    scope = "、".join(product_parts)
    topic = profile["title"]
    if variant_index < 6:
        # Deliberately near-duplicate policies: the actual technical wording is
        # preserved, but this document does not authorize the queried context.
        facts = list(profile['facts'])
        cause = '同技术症状和步骤，仅授权另一版本/环境'
        conflict = 'scope_only_near_duplicate'
    else:
        cause, diagnostic, action, verify = alternatives()[profile['family_id']]
        symptom = re.split('[，；。]', profile['facts'][0])[0]
        facts = [
            f'同主题故障记录可能描述“{symptom}”。本范围核实后的不同根因为{cause}，必须用下述证据区分，不能直接照搬生产手册。',
            f'{diagnostic}。本项是{topic}在当前环境的判别证据，记录现场结果后再决定是否操作。',
            f'确认{cause}且当前对象已获批准后，应{action}。仅限当前环境，不把该步骤用于生产故障。',
            f'以{verify}作为当前环境的恢复证据；只看到相似故障消失仍不足以通过验收。',
            f'尚未完成{diagnostic}时不得执行恢复；不得把{environment}的临时配置或凭据推广到生产。',
            f'完成{action}后仍失败时，交当前环境的{topic}负责人，附现场判别证据和配置差异，不附密码或私钥。',
        ]
        conflict = 'same_symptom_distinct_technical_root_cause'
    return {
        "id": f"negative-{profile['family_id']}-{variant_index + 1:02d}",
        "title": topic + "环境差异处置", "body": body_for(topic + "环境差异处置", scope, facts),
        "scenario": profile["scenario"], "status": "active", "valid_to": "2099-12-31",
        "kind": "distractor", "family_id": profile["family_id"], "split": split,
        "applicability": scope,
        "conflict_dimensions": ["environment", "version", conflict],
        "conflict": {"target_scope": profile["scope"], "distractor_scope": scope,
                     "root_cause": cause, "negative_reason": "incompatible_explicit_query_environment_and_version"},
        "provenance": provenance("rule_composed_same_domain_hard_negative", template_variant=variant_index + 1),
    }


def probe_data(profiles: list[dict]) -> tuple[list[dict], list[dict]]:
    docs, probes = [], []
    for i in range(4):
        p = profiles[i]
        for lifecycle in ("expired", "deleted"):
            doc = target_document(p, "probe")
            doc["id"] = f"probe-{lifecycle}-{p['family_id']}"
            doc["kind"] = "probe"
            doc["status"] = "active" if lifecycle == "expired" else "deleted"
            doc["valid_to"] = "2026-01-01" if lifecycle == "expired" else "2099-12-31"
            # Probe identities have a distinct isolated scope, so an active
            # target is not an alternative answer to an expired/deleted probe.
            old_scope = p["scope"]
            new_scope = old_scope.rsplit("、", 1)[0] + f"、已退役{lifecycle}验证网"
            doc["applicability"] = new_scope
            doc["body"] = doc["body"].replace(old_scope, new_scope)
            docs.append(doc)
            probes.append({
                "question_id": f"probe-{lifecycle}-{i + 1}", "family_id": p["family_id"], "split": "probe",
                "query": f"在{new_scope}中，{p['queries'][2]}", "question_type": lifecycle,
                "conditions": {"scope": new_scope, "required_status": "active", "as_of": "2026-11-02"},
                "gold": [], "answer": None, "excluded_document_ids": [doc["id"]],
                "expected": "abstain_or_clarify", "provenance": provenance("isolated_lifecycle_probe"),
            })
    for i, p in enumerate(profiles[4:8]):
        scope = "并购子公司隔离办公网、未纳管终端"
        probes.append({
            "question_id": f"probe-unanswerable-{i + 1}", "family_id": p["family_id"], "split": "probe",
            "query": f"在{scope}中，{p['queries'][2]}", "question_type": "unanswerable",
            "conditions": {"scope": scope, "required_status": "active", "as_of": "2026-11-02"},
            "gold": [], "answer": None, "expected": "abstain_or_clarify",
            "provenance": provenance("deliberately_uncovered_scope"),
        })
    return docs, probes


def validate(dataset: dict) -> dict:
    documents = dataset["documents"]
    questions = dataset["questions"]
    docs = {d["id"]: d for d in documents}
    assert len(docs) == len(documents), "duplicate document IDs"
    assert len({q['question_id'] for q in questions + dataset['probes']}) == len(questions) + len(dataset['probes'])
    assert Counter(d['kind'] for d in documents) == {"target": 50, "distractor": 600, "probe": 8}
    assert Counter(q['split'] for q in questions) == {"test": 240, "dev": 60}
    assert len(dataset['probes']) == 12
    family_counts = Counter(q['family_id'] for q in questions)
    assert set(family_counts.values()) == {6} and len(family_counts) == 50
    dev = {q['family_id'] for q in questions if q['split'] == 'dev'}
    test = {q['family_id'] for q in questions if q['split'] == 'test'}
    assert not dev & test
    for d in documents:
        sections = re.split(r"^## .+$", d['body'], flags=re.M)[1:]
        assert len(sections) == 6, d['id']
        assert all(100 <= len(s.strip()) <= 225 for s in sections), d['id']
        if d['kind'] != 'probe':
            assert d['split'] == ('dev' if d['family_id'] in dev else 'test')
    for q in questions:
        assert q['conditions']['scope'] in q['query']
        assert len(q['gold']) == (2 if q['question_type'] == 'cross_section' else 1)
        for gold in q['gold']:
            doc = docs[gold['document_id']]
            assert doc['kind'] == 'target' and doc['split'] == q['split']
            sections = re.split(r"^## .+$", doc['body'], flags=re.M)[1:]
            assert gold['evidence'] in sections[gold['section_index'] - 1]
            assert gold['evidence'] in q['answer']
            assert doc['id'] not in q['query'] and doc['id'] not in doc['title']
        target = docs[q['gold'][0]['document_id']]
        for d in documents:
            if d['kind'] == 'distractor' and d['family_id'] == q['family_id']:
                assert d['applicability'] != target['applicability']
                assert target['applicability'] not in d['body']
                assert 'environment' in d['conflict_dimensions']
    hashes = Counter(hashlib.sha256(d['body'].encode()).hexdigest() for d in documents)
    # Probe copies differ in lifecycle scope; exact duplicate text is disallowed.
    assert max(hashes.values()) == 1
    assert len({q['query'] for q in questions}) == 300
    # Expose lexical similarity rather than pretending templates are independent
    # incidents. Strip shared applicability before comparing intra-family tasks.
    similarities = []
    for family in family_counts:
        qs = [q['query'].split('中，', 1)[-1] for q in questions if q['family_id'] == family]
        for i, first in enumerate(qs):
            for second in qs[i + 1:]:
                similarities.append(SequenceMatcher(None, first, second).ratio())
    ordered = sorted(similarities)
    pools = dataset['default_corpora']
    assert set(pools['64']) < set(pools['256']) < set(pools['512'])
    targets = {d['id'] for d in documents if d['kind'] == 'target'}
    for size, ids in pools.items():
        assert len(ids) == int(size) and len(set(ids)) == int(size)
        assert targets <= set(ids)
        assert all(docs[doc_id]['kind'] != 'probe' for doc_id in ids)
    return {
        "documents_by_kind": dict(Counter(d['kind'] for d in documents)),
        "questions_by_split": dict(Counter(q['split'] for q in questions)),
        "families_by_split": {"test": len(test), "dev": len(dev)},
        "question_types": dict(Counter(q['question_type'] for q in questions)),
        "evidence_substrings_checked": sum(len(q['gold']) for q in questions),
        "exact_duplicate_documents": 0, "exact_duplicate_questions": 0,
        "cross_split_family_overlap": 0, "paragraph_char_range": [100, 225],
        "within_family_query_similarity_without_scope": {
            "metric": "difflib.SequenceMatcher character ratio",
            "pairs": len(similarities), "max": round(max(similarities), 4),
            "p95": round(ordered[int(len(ordered) * .95)], 4),
            "pairs_above_0_8": sum(value > .8 for value in similarities),
        },
        "limitations": "Substring/schema/overlap checks do not prove semantic annotation correctness; independent audit is required.",
    }


def build() -> dict:
    profiles = parse_profiles()
    documents, questions = [], []
    for i, profile in enumerate(profiles):
        split = "test" if i < 40 else "dev"
        documents.append(target_document(profile, split))
        questions.extend(questions_for(profile, split))
        documents.extend(distractor_document(profile, split, j) for j in range(12))
    probe_docs, probes = probe_data(profiles)
    documents.extend(probe_docs)
    target_ids = [d['id'] for d in documents if d['kind'] == 'target']
    negative_ids = sorted(d['id'] for d in documents if d['kind'] == 'distractor')
    random.Random(SEED).shuffle(negative_ids)
    dataset = {
        "metadata": {
            "schema_version": "1.0", "benchmark_id": "retrieval-2026-11-02",
            "created_at": "2026-11-02", "language": "zh-CN", "seed": SEED,
            "purpose": "semantic evidence retrieval under fixed questions and increasing same-domain distractors",
            "scope": "Offline synthetic company policies; not a vendor specification, production incident dataset, or answer-accuracy measurement.",
            "generation": {
                "targets": "50 LLM-composed fictional policy families, 6 distinct facts/tasks per family",
                "distractors": "50 families x 12 incompatible contexts: 300 near-duplicate policies with different scope, 300 family-specific alternative technical root-cause documents",
                "api_calls": 0, "external_sources": [],
                "split_unit": "family_id; 40 held-out test families and 10 dev families",
                "paragraphs": "six H2 sections, each paragraph 100-225 characters; short H1 avoids an extra intro chunk",
            },
            "scoring_contract": {
                "main_questions": 300, "test_questions": 240, "dev_questions": 60,
                "gold_unit": "document_id + H2 section; section_index corresponds to the actual splitter child seq",
                "cross_section": "both recovery section and escalation section are necessary for full evidence coverage",
                "probes": "12 separate out-of-denominator abstention/lifecycle probes; probe documents excluded from main corpora",
                "corpora": "all 50 common targets plus nested seeded samples of 14/206/462 distractors",
            },
            "limitations": [
                "LLM-authored synthetic facts and questions may favor the author's vocabulary; not blind real-user paraphrases.",
                "Targets share a six-section operational structure; background prose repeats and introduces template bias.",
                "Distractors share twelve context templates; half preserve original technical prose, half use 50 family-specific alternative technical explanations. Lexical hardness is not proof of realistic semantic difficulty.",
                "Every main query states explicit scope, making applicability discrimination easier than underspecified real requests.",
                "Family split prevents direct target/distractor family leakage between dev and test, but common section and negative templates remain shared.",
                "Evidence labels are authored alongside documents. Mechanical checks cannot substitute for independent semantic review.",
                "No result estimates real incident accuracy, enterprise scale, latency SLOs, production readiness, or a general product quality score.",
            ],
        },
        "documents": documents, "questions": questions, "probes": probes,
        "default_corpora": {str(size): target_ids + negative_ids[:size - len(target_ids)] for size in (64, 256, 512)},
    }
    dataset['metadata']['self_check'] = validate(dataset)
    return dataset


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', type=Path, default=DEFAULT_OUTPUT)
    parser.add_argument('--check-only', action='store_true', help='validate the existing dataset without rewriting')
    args = parser.parse_args()
    if args.check_only:
        result = validate(json.loads(args.output.read_text(encoding='utf-8')))
    else:
        dataset = build()
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(json.dumps(dataset, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
        result = dataset['metadata']['self_check']
    print(json.dumps({'output': str(args.output), 'self_check': result}, ensure_ascii=False, indent=2))


if __name__ == '__main__':
    main()
